const ATTR_TRANSLATIONS = { ...UI, ...EXTRA_UI, ...AUTH_AND_SUPPORT_STATES, ...SCREENSHOT_AND_CUSTOMER_PATCH, ...HEADER_ATTRIBUTES, ...LOCATION_AND_CUSTOMER_AUDIT_PATCH, ...AUTH_SECURITY_UI };

function dictionary(locale: Locale) {
  return locale === "en" ? null : { ...UI, ...EXTRA_UI, ...AUTH_AND_SUPPORT_STATES, ...SCREENSHOT_AND_CUSTOMER_PATCH, ...LOCATION_AND_CUSTOMER_AUDIT_PATCH, ...AUTH_SECURITY_UI };
}

function preserveWhitespace(source: string, translated: string) {
  const leading = source.match(/^\s*/)?.[0] ?? "";
  const trailing = source.match(/\s*$/)?.[0] ?? "";
  return `${leading}${translated}${trailing}`;
}

function dynamicTranslation(trimmed: string, locale: Locale): string | null {
  if (locale === "en") return null;

  const network = trimmed.match(/^Network Status:\s*(.+)$/i);
  if (network) {
    return locale === "fr"
      ? `État du réseau : ${translateUiText(network[1], locale)}`
      : `حالة الشبكة: ${translateUiText(network[1], locale)}`;
  }

  const tryAgain = trimmed.match(/^Try again in (\d+)s$/i);
  if (tryAgain) {
    return locale === "fr" ? `Réessayer dans ${tryAgain[1]} s` : `حاول مجددًا خلال ${tryAgain[1]} ث`;
  }

  const signedIn = trimmed.match(/^Signed in as (.+)$/i);
  if (signedIn) {
    return locale === "fr" ? `Connecté en tant que ${signedIn[1]}` : `مسجل الدخول باسم ${signedIn[1]}`;
  }

  const relative = trimmed.match(/^(\d+)(s|m|h|d) ago$/i);
  if (relative) {
    const unit = relative[2].toLowerCase();
    const frUnit = unit === "s" ? "s" : unit === "m" ? "min" : unit === "h" ? "h" : "j";
    const arUnit = unit === "s" ? "ث" : unit === "m" ? "د" : unit === "h" ? "س" : "ي";
    return locale === "fr" ? `il y a ${relative[1]} ${frUnit}` : `منذ ${relative[1]} ${arUnit}`;
  }

  return null;
}

export function translateUiText(source: string, locale: Locale): string {
  if (locale === "en" || !source) return source;
  const trimmed = source.trim();
  if (!trimmed) return source;

  const item = dictionary(locale)?.[trimmed];
  const direct = locale === "fr" ? item?.fr : locale === "ar" ? item?.ar : undefined;
  if (direct) return preserveWhitespace(source, direct);

  const dynamic = dynamicTranslation(trimmed, locale);
  if (dynamic) return preserveWhitespace(source, dynamic);

  return source;
}

export function translateUiAttribute(source: string, locale: Locale): string {
  if (locale === "en" || !source) return source;
  const item = ATTR_TRANSLATIONS[source.trim()];
  const translated = locale === "fr" ? item?.fr : locale === "ar" ? item?.ar : undefined;
  return translated ?? dynamicTranslation(source.trim(), locale) ?? source;
}
